import signal
import shutil
import subprocess
import sys
import tempfile
import threading
import time
from dataclasses import dataclass, asdict
from pathlib import Path
from typing import Callable, Iterable


RESULT_RE = re.compile(r"^.*\.(?P<line>[0-9]+)\.(?P<char>[0-9]+)\.\*\.p:")
PROBLEM_RE = re.compile(r"^(?P<prefix>.*)\.(?P<line>[0-9]+)(?:\.(?P<char>[0-9]+))?\.th0\.p$")
PROVED_RE = re.compile(r"SZS status (Theorem|Unsatisfiable|ContradictoryAxioms)\b")
FATAL_OUTPUT_RE = re.compile(r"Aborted by signal|ASSERTION|User error|missing .* implementation", re.IGNORECASE)
MEGALODON_SOURCE_LINE_RE = re.compile(r'^megalodon_source_line\("(?P<line>(?:\\.|[^"\\])*)"\)\.$')
MEGALODON_STEP_RE = re.compile(r'^megalodon_step\((?P<id>[0-9]+),"(?P<rule>(?:\\.|[^"\\])*)"')
MEGALODON_STEP_FORMULA_RE = re.compile(
    r'^megalodon_step\((?P<id>[0-9]+),"(?P<rule>(?:\\.|[^"\\])*)","[^"]*",\[[^]]*\],(?:true|false),[0-9]+,"(?P<formula>(?:\\.|[^"\\])*)"\)\.$'
)
MEGALODON_STEP_DETAIL_RE = re.compile(
    r'^megalodon_step\((?P<id>[0-9]+),"(?P<rule>(?:\\.|[^"\\])*)","[^"]*",\[(?P<parents>[0-9,]*)\],(?:true|false),[0-9]+,"(?P<formula>(?:\\.|[^"\\])*)"\)\.$'
)
MEGALODON_STEP_PROPOSITION_RE = re.compile(
    r'^megalodon_step_proposition\((?P<id>[0-9]+),"(?P<proposition>(?:\\.|[^"\\])*)"\)\.$'
)
MEGALODON_PLACEHOLDER_FORMULA_RE = re.compile(
    r'^\s*(?:tff|cnf)\(u[0-9]+,\s*plain,\s*\$true\)\.\s*$',
    re.DOTALL,
)
MEGALODON_STEP_SUBSTITUTIONS_RE = re.compile(
    r'^megalodon_step_substitutions\((?P<id>[0-9]+),\[(?P<formulas>.*)\]\)\.$'
)
MEGALODON_STEP_REPLAY_KIND_RE = re.compile(
    r'^megalodon_step_replay_kind\((?P<id>[0-9]+),"(?P<kind>(?:\\.|[^"\\])*)"\)\.$'
)
MEGALODON_STEP_VARIABLE_SORTS_RE = re.compile(
    r'^megalodon_step_variable_sorts\((?P<id>[0-9]+),\[(?P<sorts>.*)\]\)\.$'
)
MEGALODON_STEP_EXTRA_RE = re.compile(
    r'^megalodon_step_extra\((?P<id>[0-9]+),"(?P<kind>(?:\\.|[^"\\])*)",\[(?P<fields>.*)\]\)\.$'
)
MEGALODON_SYMBOL_DECLARATION_RE = re.compile(r'^megalodon_symbol_declaration\("(?P<declaration>(?:\\.|[^"\\])*)"\)\.$')
MEGALODON_FINAL_STEP_RE = re.compile(r"^megalodon_final_step\((?P<id>[0-9]+)\)\.$")
FRESH_SET_RE = re.compile(r"^sF[0-9]+$")
VAMPIRE_DEPENDENCY_RE = re.compile(r"^(s[FK]|db)[0-9]+$")
INFERRED_DEPENDENCY_RE = re.compile(r"^[_A-Za-z][_A-Za-z0-9']*$")
DEFINITION_RE = re.compile(r"^Definition (?P<name>[_A-Za-z][_A-Za-z0-9']*) : (?P<sort>[^:]+?) := (?P<body>.*)\.$")
THF_TYPE_RE = re.compile(r"^thf\([^,]+,\s*type,\s*\((?P<name>[^:\s]+)\s*:\s*(?P<sort>.*?)\)\)\.", re.DOTALL)
PROOF_SEARCH_STATE = threading.local()
PROOF_SEARCH_SECONDS = float(os.environ.get("MEGALODON_PROOF_SEARCH_SECONDS", "8"))
RAW_TPTP_REPLAY_SECONDS = float(os.environ.get("MEGALODON_RAW_TPTP_REPLAY_SECONDS", "0.35"))
RAW_TPTP_DEFINITION_REPLAY_SECONDS = float(os.environ.get("MEGALODON_RAW_TPTP_DEFINITION_REPLAY_SECONDS", "30.0"))
RAW_TPTP_FORWARD_SUBSUMPTION_REPLAY_SECONDS = float(os.environ.get("MEGALODON_RAW_TPTP_FORWARD_SUBSUMPTION_REPLAY_SECONDS", "1.0"))
RAW_TPTP_REPLAY_CHAR_LIMIT = int(os.environ.get("MEGALODON_RAW_TPTP_REPLAY_CHAR_LIMIT", "12000"))
RAW_TPTP_EXPORTED_NORMAL_FORM_CHAR_LIMIT = int(os.environ.get("MEGALODON_RAW_TPTP_EXPORTED_NORMAL_FORM_CHAR_LIMIT", "60000"))
RAW_TPTP_EXPORTED_FOOL_CHAR_LIMIT = int(os.environ.get("MEGALODON_RAW_TPTP_EXPORTED_FOOL_CHAR_LIMIT", "60000"))
RAW_TPTP_FOOL_PROOF_CHAR_LIMIT = int(os.environ.get("MEGALODON_RAW_TPTP_FOOL_PROOF_CHAR_LIMIT", "200000"))
RAW_TPTP_EXPORTED_SKOLEM_CHAR_LIMIT = int(os.environ.get("MEGALODON_RAW_TPTP_EXPORTED_SKOLEM_CHAR_LIMIT", "60000"))
RAW_TPTP_EXPORTED_RECTIFY_CHAR_LIMIT = int(os.environ.get("MEGALODON_RAW_TPTP_EXPORTED_RECTIFY_CHAR_LIMIT", "60000"))
RAW_TPTP_EXPORTED_DEFINITION_REWRITE_CHAR_LIMIT = int(os.environ.get("MEGALODON_RAW_TPTP_EXPORTED_DEFINITION_REWRITE_CHAR_LIMIT", "90000"))
RAW_TPTP_MINIMAL_DEFINITION_REPLAY_CHAR_LIMIT = int(os.environ.get("MEGALODON_RAW_TPTP_MINIMAL_DEFINITION_REPLAY_CHAR_LIMIT", "2000"))
RAW_TPTP_EXPORTED_CNF_CHAR_LIMIT = int(os.environ.get("MEGALODON_RAW_TPTP_EXPORTED_CNF_CHAR_LIMIT", "90000"))
RAW_TPTP_CLASSICAL_NORMAL_FORM_CHAR_LIMIT = int(os.environ.get("MEGALODON_RAW_TPTP_CLASSICAL_NORMAL_FORM_CHAR_LIMIT", "1500"))
PROOF_SEARCH_CLOCK = getattr(time, "thread_time", time.monotonic)
MEGALODON_ADMIT_RE = re.compile(r"\badmit\.")


def proof_search_now() -> float:
    return PROOF_SEARCH_CLOCK()


def proof_search_timed_out() -> bool:
    deadline = getattr(PROOF_SEARCH_STATE, "deadline", None)
    return deadline is not None and proof_search_now() > deadline


def has_megalodon_admit(text: str) -> bool:
    return any(MEGALODON_ADMIT_RE.search(line) for line in text.splitlines() if not line.lstrip().startswith("//"))


def raw_tptp_replay_payload_size(
    proposition: str,
    parents: list[str],
    propositions_by_name: dict[str, str],
    replay_step: "MegalodonReplayStep | None",
) -> int:
    size = len(proposition)
    size += sum(len(propositions_by_name.get(parent, "")) for parent in parents)
    if replay_step is not None:
        for kind, fields in replay_step.extras:
            size += len(kind)
            if hasattr(fields, "items"):
                size += sum(len(key) + len(value) for key, value in fields.items())
            else:
                size += sum(len(field) for field in fields)
    return size


def raw_tptp_replay_payload_size_ok(
    rule: str | None,
    proposition: str,
    parents: list[str],
    propositions_by_name: dict[str, str],
    replay_step: "MegalodonReplayStep | None",
) -> bool:
    rule_key = rule.replace(" ", "_") if rule is not None else None
    size = raw_tptp_replay_payload_size(proposition, parents, propositions_by_name, replay_step)
    if size <= RAW_TPTP_REPLAY_CHAR_LIMIT:
        return True
    if (
        rule_key in {"flattening", "ennf_transformation", "nnf_transformation", "boolean_simplification", "true_and_false_elimination"}
        and replay_step is not None
        and any(kind == "normal_form" for kind, _fields in replay_step.extras)
    ):
        return size <= RAW_TPTP_EXPORTED_NORMAL_FORM_CHAR_LIMIT
    if (
        rule_key == "fool_elimination"
        and replay_step is not None
        and any(kind == "fool" for kind, _fields in replay_step.extras)
    ):
        return size <= RAW_TPTP_EXPORTED_FOOL_CHAR_LIMIT
    if (
        rule_key == "skolemisation"
        and replay_step is not None
        and any(kind == "skolemize" for kind, _fields in replay_step.extras)
    ):
        return size <= RAW_TPTP_EXPORTED_SKOLEM_CHAR_LIMIT
    if (
        rule_key == "rectify"
        and replay_step is not None
        and any(kind == "rectify" for kind, _fields in replay_step.extras)
    ):
        return size <= RAW_TPTP_EXPORTED_RECTIFY_CHAR_LIMIT
    if (
        rule_key in {"definition_folding", "definition_unfolding"}
        and replay_step is not None
        and any(kind == "definition_rewrite" for kind, _fields in replay_step.extras)
    ):
        return size <= RAW_TPTP_EXPORTED_DEFINITION_REWRITE_CHAR_LIMIT
    if (
        rule_key == "cnf_transformation"
        and replay_step is not None
        and any(kind == "cnf" for kind, _fields in replay_step.extras)
    ):
        return size <= RAW_TPTP_EXPORTED_CNF_CHAR_LIMIT
    if (
        rule_key == "superposition"
        and replay_step is not None
        and any(kind == "two_literal_rewrite" for kind, _fields in replay_step.extras)
    ):
        return size <= RAW_TPTP_EXPORTED_CNF_CHAR_LIMIT
    return False


def raw_tptp_replay_seconds_for_rule(rule: str | None) -> float:
    if rule == "rectify":
        return max(RAW_TPTP_REPLAY_SECONDS, 1.0)
    if rule in {"definition_folding", "definition_unfolding"}:
        return max(RAW_TPTP_REPLAY_SECONDS, RAW_TPTP_DEFINITION_REPLAY_SECONDS)
    if rule == "superposition":
        return max(RAW_TPTP_REPLAY_SECONDS, 1.0)
    if rule in {"forward_subsumption_resolution", "backward_subsumption_resolution"}:
        return RAW_TPTP_FORWARD_SUBSUMPTION_REPLAY_SECONDS
    return RAW_TPTP_REPLAY_SECONDS


def vampire_exists_name_for_sort(sort: str) -> str:
    suffix = re.sub(r"[^A-Za-z0-9]+", "_", sort).strip("_")
    return f"vampire_exists_{suffix}"


def vampire_exists_definition_for_sort(sort: str, name: str | None = None) -> str:
    if name is None:
        name = vampire_exists_name_for_sort(sort)
    predicate_sort = f"({sort})->prop" if "->" in sort else f"{sort}->prop"
    return (
        f"Definition {name} : ({predicate_sort})->prop := "
        f"fun P => forall Q:prop, (forall X:{sort}, P X -> Q) -> Q."
    )


def vampire_exists_sort_from_proposition(proposition: str, name: str) -> str | None:
    pattern = re.compile(rf"\b{re.escape(name)}\s+\(fun\s+[_A-Za-z][_A-Za-z0-9']*\s*:\s*(?P<sort>.*?)\s*=>")
    match = pattern.search(proposition)
    if match is None:
        return None
    return match.group("sort").strip()


